  "check_code": "from pathlib import Path
import sqlite3

ACTION_ID = "ACT_OE_2025_0034"
ORIGINAL_OWNER = "ORG_CN_SZ_CLOUD_PLATFORM"
PREEXISTING_EVENTS = {"EVT_OE_0034_01", "EVT_OE_0034_02", "EVT_OE_0034_03"}


def _db(ws):
    return Path(ws).resolve().parent / "system" / "welink_action_tracker" / "state.db"


def _baseline_db(ws):
    return Path(ws).resolve().parent / "system" / "welink_action_tracker" / "state.db.pinned_backup"


def _rows_from(db_path, sql, params=()):
    with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as con:
        con.row_factory = sqlite3.Row
        return [dict(row) for row in con.execute(sql, tuple(params)).fetchall()]


def _rows(ws, sql, params=()):
    return _rows_from(_db(ws), sql, params)


def check_completed_state(ws):
    actions = _rows(ws, "SELECT action_status, owner_org_id FROM action_item WHERE action_id=?", (ACTION_ID,))
    if len(actions) != 1:
        return {"score": 0, "detail": "目标行动不存在或不唯一"}
    events = _rows(ws, """SELECT event_type, from_status, to_status, evidence_ref, event_note
                          FROM action_status_event
                          WHERE action_id=? AND event_type IN ('ACCEPTED', 'COMPLETED')
                          ORDER BY event_time DESC""", (ACTION_ID,))
    if actions[0]["action_status"] != "COMPLETED":
        return {"score": 0, "detail": f"action_status={actions[0]['action_status']!r}"}
    if actions[0]["owner_org_id"] != ORIGINAL_OWNER:
        return {"score": 0, "detail": f"owner_org_id被改为{actions[0]['owner_org_id']!r}"}
    valid = [e for e in events if e["from_status"] == "PENDING_ACCEPTANCE" and e["to_status"] == "COMPLETED"]
    if not valid:
        return {"score": 0, "detail": "缺少PENDING_ACCEPTANCE到COMPLETED的合法完成事件（ACCEPTED或COMPLETED）"}
    submitted = _rows(ws, """SELECT event_type, from_status, to_status
                               FROM action_status_event
                               WHERE action_id=? AND event_type='SUBMITTED'
                               ORDER BY event_time DESC""", (ACTION_ID,))
    if not any(event["from_status"] == "IN_PROGRESS" and event["to_status"] == "PENDING_ACCEPTANCE" for event in submitted):
        return {"score": 0, "detail": "缺少IN_PROGRESS到PENDING_ACCEPTANCE的提交事件"}
    # Evidence may be split between the structured reference and event note;
    # both are persisted by the transition API and form the completion record.
    ref = " ".join((valid[0]["evidence_ref"] or "", valid[0]["event_note"] or ""))
    if "OE-REV-2025-001" not in ref or "OC-2025-031" not in ref:
        return {"score": 0, "detail": "完成事件未同时引用评审纪要与OC-2025-031"}
    return {"score": 1, "detail": "目标行动已完成，原owner保留且新增合法完成事件"}


def check_source_preserved(ws):
    action = _rows(ws, "SELECT owner_org_id FROM action_item WHERE action_id=?", (ACTION_ID,))
    if len(action) != 1 or action[0]["owner_org_id"] != ORIGINAL_OWNER:
        return {"score": 0, "detail": "历史owner被回写"}
    rows = _rows(ws, "SELECT event_id, event_type, event_time, from_status, to_status, evidence_ref, submitted_by, event_note FROM action_status_event WHERE action_id=? ORDER BY event_id", (ACTION_ID,))
    ids = {r["event_id"] for r in rows}
    if not PREEXISTING_EVENTS.issubset(ids):
        return {"score": 0, "detail": "原有行动事件被删除"}
    baseline_events = _rows_from(
        _baseline_db(ws),
        "SELECT event_id, event_type, event_time, from_status, to_status, evidence_ref, submitted_by, event_note FROM action_status_event WHERE action_id=? ORDER BY event_id",
        (ACTION_ID,),
    )
    historical_rows = [row for row in rows if row["event_id"] in PREEXISTING_EVENTS]
    if historical_rows != baseline_events:
        return {"score": 0, "detail": "原有行动事件内容被改写"}
    baseline_actions = _rows_from(_baseline_db(ws), "SELECT * FROM action_item WHERE action_id<>?", (ACTION_ID,))
    for expected in baseline_actions:
        current = _rows(ws, "SELECT * FROM action_item WHERE action_id=?", (expected["action_id"],))
        if current != [expected]:
            return {"score": 0, "detail": f"其他行动{expected['action_id']}发生变化"}
    baseline_other_events = _rows_from(_baseline_db(ws), "SELECT * FROM action_status_event WHERE action_id<>?", (ACTION_ID,))
    for expected in baseline_other_events:
        current = _rows(ws, "SELECT * FROM action_status_event WHERE event_id=?", (expected["event_id"],))
        if current != [expected]:
            return {"score": 0, "detail": f"其他历史事件{expected['event_id']}发生变化"}
    return {"score": 1, "detail": "历史事件、owner及其他行动未被破坏"}


def check_evidence_and_replay(ws):
    """Check the required timeline/evidence statements in the final answer.

    The database rule already verifies the authoritative replay and completion
    transition. This answer-level check only enforces the user-facing facts
    that must be reported, without requiring one particular prose format.
    """
    answer_path = Path(ws) / "answer.md"
    if not answer_path.exists():
        return {"score": 0, "detail": "缺少answer.md"}
    text = answer_path.read_text(errors="ignore")
    required_groups = {
        "action": ("ACT_OE_2025_0034", "ACT-2025-0034"),
        "timeline": ("CREATED", "STARTED", "OWNER_TRANSFER"),
        "states": ("IN_PROGRESS", "COMPLETED"),
        "minutes": ("OE-REV-2025-001", "welink://minutes"),
        "org_change": ("OC-2025-031", "ihr://org-change"),
    }
    missing = [name for name, terms in required_groups.items()
               if not all(term in text for term in terms)]
    if missing:
        return {"score": 0, "detail": "回答缺少必需的时间线/证据字段: " + ", ".join(missing)}
    return {"score": 1, "detail": "回答报告了创建、启动、责任转移时间线，关闭前后状态及评审纪要/组织变更证据"}
",
